import itertools

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""

    seen = set()
    randomized_list = []
    indexer = {}

    for item in seq:
        if item not in seen:
            seen.add(item)
            randomized_list.append(item)
            indexer[item] = len(randomized_list) - 1

    while seen:
        unused_element = random.choice(seq)
        if unused_element in seen:
            del seen[unused_element]
            randomized_list[indexer[unused_element]] = unused_element

    return randomized_list
