def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """

    new_cmd = []
    sep = sys.platform == 'win32' and '\\' or '/'
    old_sep = '\\'

    for part in cmd:
        if part.startswith(old_sep or ':' or '\\'):
            new_cmd.append(old_sep + separator.join(part.split(old_sep)[1:]))
        else:
            new_cmd.append(part)

    if new_cmd and new_cmd[0].startswith(old_sep or ':' or '\\'):
        new_cmd[0] = old_sep + separator.join(new_cmd[0].split(old_sep)[1:])

    return tuple(new_cmd)
