def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    class ValidationError(Exception):
        def __init__(self, messages: List[Dict[str, Any]]):
            super().__init__()
            self.messages = messages

    # Regular expression patterns for label keys and values
    regexes = {
        "key1": r"\w+",  # alphanumeric characters
        "key2": r"\S+",  # non-whitespace characters
        "$$"    : r"\d+   ",  # digits with optional leading zero and a space
        True  : r"true|false",  # true or false
    }

    for key in labels.keys():
        if not isinstance(key, str):
            raise ValidationError([{'key': str(key), 'value': "label key is not a string or a bytes-like object'}])
        if key not in regexes:
            raise ValidationError([{'key': str(key), 'value': "label key does not match the regex: {}".format(regexes['key1'])}])

    for value in labels.values():
        if not isinstance(value, (str, bytes)):
            raise ValidationError([{'key': str(key), 'value': "label value is not a string or a bytes-like object'}])

    if isinstance(value, str):
        # Simple string validation using regex
        if not re.match(regexes[key], value):
            raise ValidationError([{'key': str(key), 'value': f"expected string or bytes-like object but got '{value}'"}])

    elif isinstance(value, bytes):
        if not value.isprintable():
            raise ValidationError([{'key': str(key), 'value': "expected string or bytes-like object but got a non-printable character"}])

    # Additional checks for certain keys
    if key == "key2":
        if "invalid" in value:
            raise ValidationError([{'key': str(key), 'value': "label value contains 'invalid'"}])
    elif key == "$$":
        if not re.match(regexes[key], value):
            raise ValidationError([{'key': str(key), 'value': f"expected string or bytes-like object but got '{value}'"}])
    elif key == True:
        if not re.match(regexes[key], value.lower()):
            raise ValidationError([{'key': str(key), 'value': f"expected string or bytes-like object but got '{value}'"}])
