def format(self, sql, params):
    import collections

    if isinstance(sql, str):
        sql = sql.encode('utf-8')

    in_style = self.SQLParams.in_style
    out_params = {}
    out_param_ids = None

    if isinstance(params,collections.Mapping):
        if in_style == 'named':
            for k, v in params.items():
                out_params[k] = v
            out_param_ids = list(params.keys())
        elif in_style == 'ordinal':
            out_param_ids = list(params)
            for i, v in enumerate(out_param_ids):
                out_params[v] = params[v]
    else:
        if in_style == 'named':
            raise ValueError('Expected a mapping of in-style parameters when using named parameter style.')
        elif in_style == 'ordinal':
            raise ValueError('Expected a sequence of in-style parameters when using ordinal parameter style.')

    if out_param_ids:
        formatted_sql, formatted_params = sql.replace('%', '?').format(*formatted_params)
    else:
        formatted_sql, formatted_params = sql, params

    return formatted_sql, out_params
