            out_params = {}
            for key, value in params.items():
                if value is not None:
                    out_params[key] = value
                    break
            else:
                continue  # Skip this set of parameters if none are provided

            formatted_params.append(out_params)
        elif isinstance(params, Sequence):
            out_params = []
            for item in params:
