        temp_params = {k: v for k, v in params.items()}
        if _is_named_params(params):  # Check if the parameters are named
            for name, value in temp_params.items():
                temp_params[name] = "@" + name + "@" if not value else "@" + str(value) + "@"
        elif _is_ordinal_params(params):  # Check if the parameters are ordinal
            for i, value in enumerate(temp_params):
                temp_params[i] = "@" + "p" + str(i + 1) + "@"  if not value else "@" + str(value) + "@"
        converted_params.append(temp_params)

    return formatted_sql, converted_params

def _is_named_params(params):
    return all(isinstance(k, str) for k in params.keys())

def _is_ordinal_params(params):
    return all(isinstance(k, int) for k in params.keys())
