def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("Input object must be an InventoryValidator")

        if self.doc != prior.doc:
            raise ValueError("Document IDs must match for valid prior version")

        # check for entity pair redundancy
        for pair in self.pairings:
            for prior_pair in prior.pairings:
                if pair.entity1 == prior_pair.entity1 and pair.entity2 == prior_pair.entity2:
                    raise ValueError("Duplicate entity pair found in prior version")

        # check for event redundancy
        for event in self.events:
            for prior_event in prior.events:
                if event.type == prior_event.type and event.agent == prior_event.agent and event.time == prior_event.time:
                    raise ValueError("Duplicate event found in prior version")

        # check for attribute redundancy
        for attr in self.attributes:
            for prior_attr in prior.attributes:
                if attr.name == prior_attr.name and attr.type == prior_attr.type and attr.value == prior_attr.value:
                    raise ValueError("Duplicate attribute found in prior version")

        # check for parent-child relationship redundancy
        for parent in self.parents:
            for prior_parent in prior.parents:
                if parent.id == prior_parent.id and parent.label == prior_parent.label:
                    raise ValueError("Duplicate parent-child relationship in prior version")
