def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    tree = Element(f"span{id(self)}")
    attr = self.attrib
    if attr:
        for key, value in attr.items():
            tree.set(key, value)
        tree.tag = f"{self.__class__.__name__}({ ','.join([f'{key}={value}' for key, value in attr.items()])})"
    els = []

    if not hasattr(self, "_elements") or not self._elements:
       .Elements = []
    for e in self._elements:
        if isinstance(e, AbstractElement):
            els.append(e.pretty(indent+1, debug))

    if els:
        tree.append(Element(f"child"))
        child = tree.find(f"child")
        for el in els:
            child.append(el)

    return _pretty(self, indent, debug, not els)

def _pretty(self, indent, debug, has_children=False):
    """
    Return a pretty formatted representation of self.
    """
    tree = Element(f"{self.__class__.__name__}_{id(self)}")
    attr = self.attrib
    if attr:
        for key, value in attr.items():
            tree.set(key, value)
        tree.tag = f"{self.__class__.__name__}_{id(self)}({ ','.join([f'{key}={value}' for key, value in attr.items()])})"
