def absorb(self, args):
    """Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

            A & (A | B) = A, A | (A & B) = A

    Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        # Find pairs of terms that can be absorbed
        while len(new_args) > 0 and isinstance(new_args[-1], list) and len(new_args[-1]) > 1:
            a, b = new_args.pop(-1)
            if arg == a:
                new_args[-1].append(b)
            elif arg == b:
                new_args[-1].append(a)
            else:
                new_args.append([a, b])

        # Apply negative absorption
        if new_args and isinstance(new_args[-1], list) and len(new_args[-1]) > 1 and not isinstance(new_args[-1][0], list) and not isinstance(new_args[-1][1], list):
            a, b = new_args.pop(-1)
            if not isinstance(a, list) and not isinstance(b, list):
                a = [a]
            if not isinstance(b, list) and not isinstance(a, list):
                b = [b]
            b_mask = [1] * len(b)
            for i in range(len(a)):
                if a[i] != b[i]:
                    b_mask[i] = 0
            new_args.append([a[i] and b[i] for i in range(len(new_args[-1]))])

    return new_args
