            if not root_inventory:
                raise ValueError("Root inventory not found.")

            content_digests = {}
            for digest, value in inventory.items():
                if digest not in root_inventory:
                    content_digests[digest] = value
                    break

            if not content_digests:
                raise ValueError("No content digests found.")

        # Check the content digest against the root inventory
        for digest, value in content_digests.items():
            if digest != root_inventory[digest]:
