import re

class BugzillaParams:
    def __init__(self, params):
        self.params = params

    def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""

        # Check if params is already an instance of BugzillaParams
        if not isinstance(params, BugzillaParams):
            raise ValueError("params must be an instance of BugzillaParams")

        # Check if bug_ids is a list or tuple of integers
        if not isinstance(bug_ids, (list, tuple)):
            raise ValueError("bug_ids must be a list or tuple of integers")

        # Remove any existing bug IDs from the params dictionary
        for bug_id in bug_ids:
            if bug_id in self.params.keys():
                del self.params[bug_id]

        # Add the new bug IDs to the params dictionary
        for bug_id in params:
            if isinstance(bug_id, int) and not (bug_id <= 0):
                self.params[bug_id] = params[bug_id]

    def convert_default_params(self):
        """Convert default bugzilla params"""

        # Find all occurrences of combined/single bugzilla params
        combined_params = re.findall(r"[^\s]+ ", self.params)

        # Convert each param to a dictionary with the bug ID as the key
        converted_params = {}
        for param in combined_params:
            parts = param.split(' ')
            if len(parts) == 2:
                converted_params[parts[0]] = parts[1]

        # Return the converted parameters
        return converted_params
