from ruamel.yaml.nodes import ScalarNode, MappingNode

def deep_merge_nodes(nodes: Sequence[tuple[ScalarNode, MappingNode]]) -> list[tuple[ScalarNode, MappingNode]]:
    merged_entities = {}

    for key, entity in nodes:
        existing_entity = merged_entities.get(key, entity)
        if isinstance(existing_entity, MappingNode):
            merged_entity = _deep_merge_mappings(existing_entity, entity)
        elif isinstance(existing_entity, ScalarNode):
            if not isinstance(existing_entity, type(entity)):
                continue
        else:
            if not isinstance(existing_entity, type(entity)) or isinstance(existing_entity, Sequence):
                continue
            if len(existing_entity) != len(entity):
                continue
            if isinstance(existing_entity, MappingNode):
                merged_entity = _deep_merge_mappings(existing_entity, entity)
            else:
                merged_entity = existing_entity
        merged_entities[key] = merged_entity

    return list(merged_entities.items())

def _deep_merge_mappings(base: MappingNode, other: MappingNode) -> MappingNode:
    if len(base) == len(other) and all(isinstance(a, MappingNode) and isinstance(b, MappingNode) for a, b in zip(base, other)):
        child_entities = {}
        for key, value in base.items():
            other_value = other.setdefault(key, value)
            if isinstance(other_value, MappingNode) and isinstance(value, MappingNode):
                if key not in child_entities:
                    child_entities[key] = []
                child_entities[key].append(_deep_merge_mappings(value, other_value))
            elif isinstance(other_value, MappingNode) and not isinstance(value, MappingNode):
                if key not in child_entities:
                    child_entities[key] = []
                child_entities[key].append(other_value)
            elif not isinstance(other_value, MappingNode) and isinstance(value, MappingNode):
                if key not in child_entities:
                    child_entities[key] = []
                child_entities[key].append(value)
            elif not isinstance(other_value, MappingNode) and not isinstance(value, MappingNode):
                child_entities[key] = [other_value, value]

        for key, value in other.items():
            if key not in base or not isinstance(value, MappingNode):
                child_entities[key] = [value]

        merged_base = MappingNode(tag=base.tag, value=child_entities.values())
        return merged_base
    else:
        raise ValueError("Incompatible structures")
