def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    argument_groups = {}
    for name in subparsers:
        argument_groups[name] = subparsers[name].add_argument_group('Common arguments')

    parsed_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        if arg.startswith('--'):
            parts = arg.split('=', 1)
            option = parts[0].lstrip('-')
            value = parts[1] if len(parts) == 2 else None
            required_attribute = None
            matched_argument = None

            for name in subparsers:
                argument_group = argument_groups[name]
                options = argument_group._get_option_name_splitter(option)
                for option in options:
                    if option in argument_group._actions and hasattr(argument_group._actions[option], 'required_attribute'):
                        required_attribute = argument_group._actions[option].required_attribute
                        matched_argument = argument_group._actions[option]
                        break
                else:
                    continue

                if required_attribute is None:
                    required_attribute = None

                namespace = None
                if matched_argument.type == argparse.TYPE_ARGPARSE:
                    namespace = subparsers[name].parse_args([])

                namespace.__dict__.update(matches=value, require=required_attribute)

                if isinstance(namespace, dict):
                    parsed_args[name] = namespace
                else:
                    parsed_args[name] = name

                break

            if matched_argument is None:
                remaining_args.append(arg)

    return parsed_args, remaining_args
