def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    try:
        parsed_uri = urllib.parse.urlparse(image_href)
        if not parsed_uri.scheme or not parsed_uri.netloc:
            raise ValueError("Invalid URL: missing scheme or netloc")
        image_id = urllib.parse.quote(parsed_uri.path, safe='')
        netloc = parsed_uri.netloc
        use_ssl = parsed_uri.scheme == 'https'
        return (image_id, netloc, use_ssl)
    except ValueError as e:
        raise ValueError(f"Invalid URL: {e}")

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    parts = urllib.parse.urlparse(image_href)
    if not parts.scheme or not parts.netloc or not parts.netloc.endswith('.jpg') or not parts.netloc.endswith('.png'):
        raise ValueError(f"Invalid image href: {image_href}")
    return parts.netloc, parts.scheme, parts.netloc.endswith('.jpg')

