from typing import List, Dict, Any, Callable

class Graph:
    def __init__(self, field_names: List[str], scale: bool = False):
        self.field_names = field_names
        self.scale = scale

class Histogram:
    def __init__(self, bins: List[float], context: Any = None):
        self.bins = bins
        self.context = context

def hist_to_graph(hist: Histogram, make_value: Callable[[float], Any], get_coordinate: str = "left",
                  field_names: List[str] = ("x", "y"), scale: bool = False) -> Graph:
    values = [make_value(bin_) for bin_ in hist.bins]
    graph = Graph(field_names)
    if get_coordinate == "left":
        x_values = [i for i in range(len(values))]
    elif get_coordinate == "right":
        x_values = [i + 0.5 for i in range(len(values))]
    elif get_coordinate == "middle":
        x_values = [(i + 0.5) / 2 for i in range(len(values))]
    else:
        raise ValueError("Invalid value for get_coordinate")
    graph.x_values = x_values
    graph.y_values = values
    if scale and graph.scale:
        graph.x_scale =hist.scale
        graph.y_scale = hist.scale
    return graph
