def find_tags(text: str, replacer: callable = None) -> Tuple[set, str]:
    """
    Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()  # Using a set here guarantees uniqueness
    current = ''  # Buffer for the current tag being processed

    in_code = False

    for char in text:
        if char == '{':
            in_code = True
            if current:
                tags.add(current.lower())  # Convert to lowercase
                if replacer:
                    current = replacer(current)
                current = ''
        elif char == '}':
            in_code = False
            if current:
                tags.add(current.lower())  # Convert to lowercase
                if replacer:
                    current = replacer(current)
                current = ''
        elif not in_code and current:
            current += char

    return tags, text

