    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    # Attempt to parse the document as JSON
    try:
        data = json.loads(document)
        if not 'subject' in data:
            raise ValueError("Invalid JSON webfinger document")
    except json.JSONDecodeError:
        # Otherwise, parse the document as XML
        try:
            root = ET.fromstring(document)
            if not 'subject' in root.attrib:
                raise ValueError("Invalid XML webfinger document")
        except ET.ParseError:
            raise ValueError("Invalid webfinger document format")

    parsed_info = {}

    if 'protocol' in data or 'xmlns:diaspora' in data:
        parsed_info['protocol'] = data.get('protocol', 'http://www.w3.org/2007/app')
        parsed_info['url'] = data.get('url', None)
        parsed_info[' subjects'] = data.get('subject', [])
    else:
        parsed_info['url'] = root.attrib['href']
        parsed_info['subjects'] = root.find('.//dc:title').text.split(';')

    if 'property' in data or 'xmlns:dc' in data and 'dc:title' in data:
        parsed_info['property'] = data.get('property', '').split(';')
    else:
        parsed_info['property'] = root.findall('.//dc:title').text.split(';')

