    """Create a new IniType complex type
    """
    settings_files = []
    if spec_option == 'all':
        for settings_dir in settings_dirs:
            try:
                settings_files += glob.glob(os.path.join(settings_dir, 'settings*'))
            except Exception as e:
                print(f"Error reading settings directory {settings_dir}: {e}")
    elif spec_option == 'names':
        settings_files = [os.path.basename(os.path.abspath(settings_dir)) for settings_dir in settings_dirs]
    else:
        raise ValueError("Invalid spec_option. Please use 'all' or 'names'.")

    return settings_files

